import {fit,silhouette,rng,tsneSettings} from './core.js';
self.onmessage=async({data})=>{try{if(data.type==='fit'){let model=fit(data.X,data.k,data.settings);model.silhouette=silhouette(data.X,model.labels);postMessage({type:'done',model});}else{tsneSettings(data.X.length,data.settings);Math.random=rng(data.settings.seed);self.window=self;await import('./vendor/tsne.js');let t=new self.tsnejs.tSNE({dim:data.settings.dimensions??2,perplexity:data.settings.perplexity,epsilon:data.settings.learningRate});t.initDataRaw(data.X);for(let i=0;i<data.settings.iterations;i++){t.step();if(i%25===0)postMessage({type:'progress',iteration:i+1});}const points=t.getSolution().map(r=>Array.from(r));if(points.flat().some(v=>!Number.isFinite(v)))throw Error('t-SNE produced nonfinite values. Try a lower learning rate.');postMessage({type:'done',points});}}catch(e){postMessage({type:'error',message:e.message});}};
